def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    w = n if n < 10 else 10
    recent_opp_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
    recent_opp_c = w - recent_opp_d

    start = n - 12
    if start < 1:
        start = 1

    after_d_tot = 0
    after_d_coop = 0
    after_c_tot = 0
    after_c_coop = 0

    for i in range(start, n):
        prev_my = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_my == 'C':
            after_c_tot += 1
            if cur_opp == 'C':
                after_c_coop += 1
        else:
            after_d_tot += 1
            if cur_opp == 'C':
                after_d_coop += 1

    if after_d_tot:
        rate_d = after_d_coop / float(after_d_tot)
    else:
        rate_d = 1.0 if opp_c == n else 0.0

    if after_c_tot:
        rate_c = after_c_coop / float(after_c_tot)
    else:
        rate_c = 1.0 if opp_c >= int(n * 0.8) else 0.0

    if opp_c == 0:
        return 'D'

    if last_opp == 'C':
        if opp_d <= max(1, n // 5):
            if after_d_tot > 0 and rate_d > 0.65 and my_d_streak <= 2:
                return 'D'
            return 'C'

        if opp_d > int(n * 0.25) and recent_opp_d >= 3 and my_d_streak <= 3:
            if after_d_tot > 0:
                if rate_d > 0.55:
                    return 'D'
                if recent_opp_c >= max(2, int(w * 0.55)):
                    return 'C'
                return 'D'
            if rng.random() < 0.16:
                return 'D'
            return 'C'

        if recent_opp_c >= max(3, int(w * 0.6)):
            return 'C'

        if opp_d > int(n * 0.55) and recent_opp_c <= max(1, w // 3):
            return 'D'

        return 'C'

    if opp_d_streak <= 4 and opp_d <= max(3, n // 3) and recent_opp_d <= 4:
        if n >= 6 or opp_c >= int(n * 0.7):
            return 'C'

    if last_my == 'D':
        if opp_d > int(n * 0.72) or recent_opp_d >= int(w * 0.8):
            if opp_c > 0 and opp_d_streak <= 6 and recent_opp_c > 0 and rng.random() < 0.04:
                return 'C'
            return 'D'

        if opp_c > 0:
            if dd_streak >= 3:
                return 'C'
            if dd_streak == 2 and rng.random() < 0.22:
                return 'C'
            if opp_d_streak <= 5 and recent_opp_c > 0 and rng.random() < 0.12:
                return 'C'

        return 'D'

    if opp_d > max(6, int(n * 0.35)) and recent_opp_d >= 3:
        return 'D'

    if opp_d_streak >= 5 and my_c_streak >= 2:
        return 'D'

    if recent_opp_d >= int(w * 0.7):
        return 'D'

    if opp_d <= max(2, n // 5):
        return 'C'

    if opp_d_streak <= 2 and recent_opp_c >= max(3, int(w * 0.6)):
        return 'C'

    if rate_c > 0.6 and opp_d_streak <= 3 and recent_opp_d <= 5:
        if rng.random() < 0.35:
            return 'C'

    return 'D'
